import { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { TrendingUp, RefreshCw, ChevronUp, ChevronDown } from 'lucide-react';
import { logger, scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import ReactECharts from 'echarts-for-react';
import type { ThemeConfig } from '@/lib/theme';

// EXPORTS: ExchangeRateChart

// 监控的货币对（兑人民币 CNY）
const TRACKED_CURRENCIES = ['USD', 'JPY', 'THB'] as const;
type TrackedCurrency = typeof TRACKED_CURRENCIES[number];

// 存储 key
const STORAGE_KEY = 'exchange-rate-history';
const LAST_FETCH_KEY = 'exchange-rate-last-fetch';

// 30 分钟刷新间隔（毫秒）
const REFRESH_INTERVAL = 12 * 60 * 60 * 1000;

// 兜底汇率值（API 失败时用）
const FALLBACK_RATES: Record<TrackedCurrency, number> = {
  USD: 7.25,
  JPY: 0.048,
  THB: 0.205,
};

interface HistoryRecord {
  date: string; // YYYY-MM-DD
  rates: Record<TrackedCurrency, number>;
}

interface ExchangeRateChartProps {
  theme: ThemeConfig;
}

// 获取本地历史记录
function getHistory(): HistoryRecord[] {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) return parsed.slice(-30);
    return [];
  } catch {
    return [];
  }
}

// 保存历史记录（最多保留 30 天）
function saveHistory(records: HistoryRecord[]) {
  try {
    const trimmed = records.slice(-30);
    scopedStorage.setItem(STORAGE_KEY, JSON.stringify(trimmed));
  } catch (err) {
    logger.warn('保存汇率历史失败:', String(err));
  }
}

// 今天日期字符串
function todayStr(): string {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

// 从 open.er-api.com 获取最新汇率
async function fetchLatestRates(): Promise<Record<TrackedCurrency, number> | null> {
  try {
    const symbols = TRACKED_CURRENCIES.join(',');
    const res = await fetch(
      `https://open.er-api.com/v6/latest/CNY?symbols=${symbols}`,
    );
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    if (data?.rates) {
      const result: Record<string, number> = {};
      for (const c of TRACKED_CURRENCIES) {
        const rate = Number(data.rates[c]);
        // API 返回的是 1 CNY = X 外币，要转成 1 外币 = X CNY
        if (rate && rate > 0) {
          result[c] = Number((1 / rate).toFixed(4));
        }
      }
      if (Object.keys(result).length > 0) {
        return result as Record<TrackedCurrency, number>;
      }
    }
    return null;
  } catch (err) {
    logger.warn('汇率API请求失败:', String(err));
    return null;
  }
}

// 货币对展示名
const CURRENCY_LABELS: Record<TrackedCurrency, string> = {
  USD: '美元 / 人民币',
  JPY: '日元 / 人民币',
  THB: '泰铢 / 人民币',
};

// 货币颜色（波普风高饱和）
const CURRENCY_COLORS: Record<TrackedCurrency, string> = {
  USD: '#2563EB', // 亮蓝
  JPY: '#DC2626', // 鲜红
  THB: '#059669', // 翠绿
};

export default function ExchangeRateChart({ theme }: ExchangeRateChartProps) {
  const [open, setOpen] = useState(false);
  const [history, setHistory] = useState<HistoryRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [lastUpdated, setLastUpdated] = useState<string>('');
  const [currentRates, setCurrentRates] = useState<Record<TrackedCurrency, number>>(FALLBACK_RATES);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // 加载历史 + 初始化
  useEffect(() => {
    const hist = getHistory();
    setHistory(hist);

    // 如果今天没有记录，尝试获取最新
    const today = todayStr();
    const todayRec = hist.find((h) => h.date === today);
    if (todayRec) {
      setCurrentRates(todayRec.rates);
      setLastUpdated(today);
    }

    // 检查是否需要刷新
    const lastFetch = Number(scopedStorage.getItem(LAST_FETCH_KEY) || '0');
    if (Date.now() - lastFetch > REFRESH_INTERVAL) {
      refreshRates();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 每 12 小时自动刷新
  useEffect(() => {
    timerRef.current = setInterval(() => {
      refreshRates();
    }, REFRESH_INTERVAL);
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const refreshRates = useCallback(async () => {
    if (loading) return;
    setLoading(true);
    try {
      const rates = await fetchLatestRates();
      if (rates) {
        const today = todayStr();
        setCurrentRates(rates);
        setLastUpdated(today);

        // 更新历史
        const hist = getHistory();
        const idx = hist.findIndex((h) => h.date === today);
        if (idx >= 0) {
          hist[idx] = { date: today, rates };
        } else {
          hist.push({ date: today, rates });
        }
        const trimmed = hist.slice(-30);
        saveHistory(trimmed);
        setHistory(trimmed);
        scopedStorage.setItem(LAST_FETCH_KEY, String(Date.now()));
      }
    } finally {
      setLoading(false);
    }
  }, [loading]);

  // 计算涨跌（与昨天比）
  const changes = useMemo(() => {
    const result: Record<TrackedCurrency, number> = { USD: 0, JPY: 0, THB: 0 };
    if (history.length < 2) return result;
    const last = history[history.length - 1].rates;
    const prev = history[history.length - 2].rates;
    for (const c of TRACKED_CURRENCIES) {
      if (prev[c] > 0) {
        result[c] = Number((((last[c] - prev[c]) / prev[c]) * 100).toFixed(2));
      }
    }
    return result;
  }, [history]);

  // ECharts 配置
  const chartOption = useMemo(() => {
    const dates = history.map((h) => h.date.slice(5)); // MM-DD
    const series = TRACKED_CURRENCIES.map((cur) => ({
      name: cur,
      type: 'line',
      smooth: true,
      symbol: history.length <= 7 ? 'circle' : 'none',
      symbolSize: 6,
      lineStyle: {
        width: 2.5,
        color: CURRENCY_COLORS[cur],
      },
      itemStyle: {
        color: CURRENCY_COLORS[cur],
        borderWidth: 2,
        borderColor: '#fff',
      },
      areaStyle: {
        color: {
          type: 'linear',
          x: 0, y: 0, x2: 0, y2: 1,
          colorStops: [
            { offset: 0, color: CURRENCY_COLORS[cur] + '25' },
            { offset: 1, color: CURRENCY_COLORS[cur] + '00' },
          ],
        },
      },
      data: history.map((h) => h.rates[cur]),
    }));

    return {
      backgroundColor: 'transparent',
      tooltip: {
        trigger: 'axis',
        backgroundColor: 'rgba(255, 255, 255, 0.98)',
        borderColor: 'rgba(0, 0, 0, 0.1)',
        borderWidth: 2,
        borderRadius: 8,
        padding: [8, 12],
        textStyle: {
          color: '#111',
          fontSize: 12,
        },
        extraCssText: 'box-shadow: 3px 3px 0 rgba(0,0,0,0.1);',
      },
      legend: {
        data: TRACKED_CURRENCIES.map((c) => c),
        top: 0,
        right: 0,
        textStyle: { fontSize: 11, color: '#666' },
        itemWidth: 20,
        itemHeight: 2,
      },
      grid: {
        left: 8,
        right: 8,
        top: 32,
        bottom: 24,
        containLabel: true,
      },
      xAxis: {
        type: 'category',
        data: dates,
        boundaryGap: false,
        axisLine: {
          lineStyle: { color: '#ddd', width: 1 },
        },
        axisTick: { show: false },
        axisLabel: {
          color: '#999',
          fontSize: 10,
          interval: Math.floor(history.length / 6),
        },
      },
      yAxis: {
        type: 'value',
        axisLine: { show: false },
        axisTick: { show: false },
        splitLine: {
          lineStyle: {
            color: '#f0f0f0',
            type: 'dashed',
          },
        },
        axisLabel: {
          color: '#999',
          fontSize: 10,
        },
        scale: true,
      },
      series,
    };
  }, [history]);

  // 格式化汇率
  function fmtRate(rate: number, cur: TrackedCurrency): string {
    if (cur === 'JPY') return rate.toFixed(4);
    if (cur === 'THB') return rate.toFixed(4);
    return rate.toFixed(4);
  }

  // 按钮上显示主汇率（取第一个 USD）
  const displayRate = currentRates.USD || FALLBACK_RATES.USD;

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <button
          className="w-full flex items-center justify-between px-2.5 py-2 rounded-lg text-xs transition-all duration-200 hover:bg-white/60 group"
          style={{
            backgroundColor: theme.primary + '10',
            border: `1.5px solid ${theme.primary}30`,
          }}
          title="查看汇率走势"
        >
          <div className="flex items-center gap-2">
            <TrendingUp
              className="size-3.5 shrink-0"
              style={{ color: theme.primary }}
            />
            <span className="font-semibold" style={{ color: theme.primaryDark }}>
              汇率
            </span>
          </div>
          <div className="flex items-center gap-1">
            <span
              className="text-[11px] font-bold tabular-nums"
              style={{ color: theme.primaryDark }}
            >
              ¥{displayRate.toFixed(2)}
            </span>
            {history.length >= 2 && changes.USD !== 0 && (
              <span
                className="text-[10px] font-medium flex items-center"
                style={{ color: changes.USD > 0 ? '#DC2626' : '#059669' }}
              >
                {changes.USD > 0 ? (
                  <ChevronUp className="size-3" />
                ) : (
                  <ChevronDown className="size-3" />
                )}
              </span>
            )}
          </div>
        </button>
      </DialogTrigger>

      <DialogContent className="sm:max-w-[560px] w-[95vw] p-0 overflow-hidden">
        <div className="p-4 pb-2">
          <DialogHeader>
            <DialogTitle className="flex items-center justify-between">
              <span className="flex items-center gap-2">
                <TrendingUp className="size-5" style={{ color: theme.primary }} />
                汇率走势 · 近30天
              </span>
              <Button
                variant="ghost"
                size="sm"
                onClick={refreshRates}
                disabled={loading}
                className="h-7 text-xs"
              >
                <RefreshCw
                  className={`size-3.5 mr-1 ${loading ? 'animate-spin' : ''}`}
                />
                刷新
              </Button>
            </DialogTitle>
          </DialogHeader>
        </div>

        <div className="px-4 pb-4">
          {/* 图表区 */}
          <Card className="mb-4 overflow-hidden">
            <CardContent className="p-3">
              {history.length === 0 ? (
                <div className="h-[150px] flex items-center justify-center text-sm text-muted-foreground">
                  {loading ? '加载中...' : '暂无历史数据，点击刷新获取'}
                </div>
              ) : (
                <ReactECharts
                  option={chartOption}
                  style={{ height: 180, width: '100%' }}
                  opts={{ renderer: 'svg' }}
                />
              )}
            </CardContent>
          </Card>

          {/* 当前汇率卡片 */}
          <div className="grid grid-cols-3 gap-2">
            {TRACKED_CURRENCIES.map((cur) => {
              const rate = currentRates[cur];
              const change = changes[cur];
              const isUp = change > 0;
              return (
                <Card key={cur} className="overflow-hidden">
                  <CardContent className="p-3">
                    <div className="flex items-center gap-1.5 mb-1.5">
                      <div
                        className="w-2 h-2 rounded-full shrink-0"
                        style={{ backgroundColor: CURRENCY_COLORS[cur] }}
                      />
                      <span className="text-[11px] text-muted-foreground font-medium truncate">
                        {CURRENCY_LABELS[cur]}
                      </span>
                    </div>
                    <div
                      className="text-lg font-black tabular-nums leading-tight"
                      style={{ color: CURRENCY_COLORS[cur] }}
                    >
                      {fmtRate(rate, cur)}
                    </div>
                    <div className="flex items-center gap-0.5 mt-0.5">
                      <Badge
                        variant={isUp ? 'destructive' : 'outline'}
                        className="text-[10px] h-4 px-1 font-semibold"
                        style={
                          !isUp
                            ? { color: '#059669', borderColor: '#059669' }
                            : undefined
                        }
                      >
                        {isUp ? (
                          <ChevronUp className="size-2.5 mr-0.5" />
                        ) : (
                          <ChevronDown className="size-2.5 mr-0.5" />
                        )}
                        {Math.abs(change).toFixed(2)}%
                      </Badge>
                      <span className="text-[10px] text-muted-foreground ml-1">
                        今日
                      </span>
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>

          {/* 数据来源说明 */}
          <div className="mt-3 flex items-center justify-between text-[10px] text-muted-foreground">
            <span>
              数据来源：open.er-api.com · 每12小时自动刷新
            </span>
            {lastUpdated && <span>更新：{lastUpdated}</span>}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
